export interface VariantAttrSelection {
  name: string;
  value: string;
  options: string[];
  isAuto: boolean;
}

// One physical serial unit's warranty, resolved at the moment it was
// captured on the serial picker (GRN / Direct PI) — either computed from a
// manufacturing date + term, or entered straight as a warranty-upto date.
// Mirrors inv_serial_units' own manufacturing_date/warranty_term_months/
// warranty_upto/warranty_mode columns (migration 237).
export interface SerialWarrantyEntry {
  mode: 'term' | 'straight';
  manufacturing_date: string | null;
  warranty_term_months: number | null;
  warranty_upto: string | null;
}

interface ProductApplicableVariantAttributeRow {
  variant_id: number;
  variant_name: string;
  variant_label: string;
  attribute_name: string;
  attribute_value: string;
  index: number;
}

interface GrnExpandedColumn {
  key: string;
  label: string;
}

interface GridExportPayload {
  title: string;
  fields: Array<[string, string]>;
  columns: string[];
  rows: string[][];
  summary?: Array<[string, string]>;
  notes?: string;
  notesLabel?: string;
  terms?: string[];
  bankDetails?: Array<[string, string]>;
  orientation?: 'portrait' | 'landscape';
  fileName?: string;
}

export interface PriceHintView {
  message: string;
  severity: 'info' | 'warn' | 'error';
  fingerprint: string;
}

export interface EntryLineColumnView {
  options: string[];
  controlValue: any;
  usesMultiSelect: boolean;
  inputType: 'number' | 'text' | 'date';
  placeholder: string;
  stockHint: string;
  stockHintClass: string;
  priceHint: PriceHintView | null;
}

export interface EntryLineRowView {
  columns: EntryLineColumnView[];
  attrSelections: VariantAttrSelection[];
  serialNames: string[];
}

interface ManufacturingBomRecord {
  bomCode: string;
  finishedProduct: string;
  version: string;
  rawMaterials: string[];
  quantityPerUnit: number;
  wastagePercent: number;
  productionCost: number;
  status: string;
}

interface GlobalContactOption {
  id?: number;
  name: string;
  type: 'Company' | 'Individual';
  mobile: string;
  email: string;
  gstin: string;
  pan: string;
  address: string;
  isSupplier?: boolean;
  isCustomer?: boolean;
  isChannelPartner?: boolean;
  // Which backing table `id` points into — 'inv_contacts' for the
  // "+Add Global Contact" quick-add store, 'global_contact' for legacy
  // Accounts contacts (tbl_mst_contact). Undefined for the static demo array.
  source?: 'inv_contacts' | 'global_contact';
}

// Round 1 (Warehouse/Branch independent stock): the merged Warehouse/Branch
// picker shared by GRN, Purchase Invoice, Purchase Return and Delivery
// Challan. Each option carries what KIND of location it is and which master
// row it came from, so a selection never has to be re-identified by matching
// its name string back against two different masters.
type MergedLocationType = 'warehouse' | 'branch';

interface MergedLocationEntry {
  label: string;
  type: MergedLocationType;
  /** Master row id; null only when the label has no matching master row. */
  id: number | null;
}

/** What the grouped dropdown binds to — `label` remains the bound value. */
interface MergedLocationOption extends MergedLocationEntry {
  group: string;
}

interface MergedLocationResolution {
  type: MergedLocationType | null;
  warehouse: WarehouseItem | null;
  branch: BranchInvItem | null;
}

// Item 13: one entry per distinct source warehouse an auto-transfer plan
// needs to draw from -- see planInterbranchAutoTransfers().
interface InterbranchTransferPlanItem {
  productId: number | null;
  productName: string;
  productCode: string | null;
  variantId: number | null;
  variantName: string | null;
  attributeId: number | null;
  attributeName: string | null;
  attributeValue: string | null;
  uomId: number | null;
  uomName: string | null;
  qty: number;
}

// Full Warehouse/Branch Independence: a group now sources from EITHER a
// warehouse OR a branch directly (fn_post_stock_transfer, migration 160,
// already accepts a branch-sourced transfer) -- the two id/name pairs are
// mutually exclusive per group, exactly one is ever populated.
interface InterbranchTransferPlanGroup {
  fromWarehouseId?: number | null;
  fromWarehouseName?: string | null;
  fromBranchId?: number | null;
  fromBranchName?: string | null;
  toWarehouseId: number;
  toWarehouseName: string;
  items: InterbranchTransferPlanItem[];
}

interface PartyRecentTransaction {
  ref: string;
  date: string;
  amount: string;
  status: string;
}

interface PartySummaryData {
  name: string;
  creditLimit: string;
  creditUsed: string;
  creditAvailable: string;
  overdueAmount: string;
  lastTransactionDate: string;
  lastTransactionAmount: string;
  recentTransactions: PartyRecentTransaction[];
}

